// Inlines the final wordmark SVGs so the mockup works from file:// (fetch is blocked there).
// node build-data.mjs  ->  wordmark-data.js
import { readFileSync, writeFileSync } from 'node:fs';
const dir = new URL('../logo/final/', import.meta.url);
const read = (n) => readFileSync(new URL(n, dir), 'utf8').replace(/<title>.*?<\/title>/, '').trim();
writeFileSync(new URL('wordmark-data.js', import.meta.url),
  '// Generated by build-data.mjs from design-preview/logo/final. Do not edit.\n' +
  'window.WORDMARK = ' + JSON.stringify({ light: read('wordmark.svg'), dark: read('wordmark-dark.svg') }) + ';\n');
console.log('wrote wordmark-data.js');
